import{_ as e,o as r,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"為替レート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/05-exchange-rate-guide.md","filePath":"v1/ja/guide/05-exchange-rate-guide.md"}'),i={name:"v1/ja/guide/05-exchange-rate-guide.md"};function o(h,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="為替レート" tabindex="-1">為替レート <a class="header-anchor" href="#為替レート" aria-label="Permalink to &quot;為替レート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>Koala は複数通貨に対応しており、為替レートの確認や通貨切り替えができます。</p><hr><h2 id="💰-基軸通貨-本位幣" tabindex="-1">💰 基軸通貨（本位幣） <a class="header-anchor" href="#💰-基軸通貨-本位幣" aria-label="Permalink to &quot;💰 基軸通貨（本位幣）&quot;">​</a></h2><p>帳本の基本となる通貨で、金額表示や集計の基準になります。</p><p>主な用途：</p><ul><li>アプリ内の金額表示の基準</li><li>概覧・統計の計算基準</li><li>為替一覧の基準（基軸通貨に対するレート表示）</li></ul><h2 id="🚀-切り替え方法" tabindex="-1">🚀 切り替え方法 <a class="header-anchor" href="#🚀-切り替え方法" aria-label="Permalink to &quot;🚀 切り替え方法&quot;">​</a></h2><ul><li>設定 → 通貨設定 → 基軸通貨</li><li>帳本管理 → 帳本詳細 → 帳本通貨</li></ul><p>切り替え後、アプリ内の表示や集計が更新されます。</p><hr><h2 id="📊-為替一覧の見方" tabindex="-1">📊 為替一覧の見方 <a class="header-anchor" href="#📊-為替一覧の見方" aria-label="Permalink to &quot;📊 為替一覧の見方&quot;">​</a></h2><ul><li>対応通貨の一覧を表示</li><li>基軸通貨に対するレートを表示</li><li>右上の更新ボタンで最新のレートを取得</li></ul><blockquote><p>💡 ヒント：ネットワークに接続できない場合は、直近のレート（キャッシュ）を使うことがあります。</p></blockquote><h2 id="💱-表示について" tabindex="-1">💱 表示について <a class="header-anchor" href="#💱-表示について" aria-label="Permalink to &quot;💱 表示について&quot;">​</a></h2><p>換算表示は <strong>現在の為替レート</strong> を使います。レート更新や基軸通貨の変更後、過去の換算表示が変わる場合があります（元の取引金額は変わりません）。</p><hr><h2 id="🔄-キャッシュについて" tabindex="-1">🔄 キャッシュについて <a class="header-anchor" href="#🔄-キャッシュについて" aria-label="Permalink to &quot;🔄 キャッシュについて&quot;">​</a></h2><p>Koala は表示や計算を高速にするため、為替レートをアプリ内で一時的に保持します。</p><ul><li>手動更新、基軸通貨の変更、帳本通貨の変更時にレートが更新されます</li></ul><hr><h2 id="⚙️-手動でレートを変更する" tabindex="-1">⚙️ 手動でレートを変更する <a class="header-anchor" href="#⚙️-手動でレートを変更する" aria-label="Permalink to &quot;⚙️ 手動でレートを変更する&quot;">​</a></h2><p>一部の通貨は、為替設定画面から手動でレートを入力できます。保存すると、そのレートが表示や計算に反映されます。</p><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-基軸通貨を変えると過去の明細金額は変わりますか" tabindex="-1">Q1：基軸通貨を変えると過去の明細金額は変わりますか？ <a class="header-anchor" href="#q1-基軸通貨を変えると過去の明細金額は変わりますか" aria-label="Permalink to &quot;Q1：基軸通貨を変えると過去の明細金額は変わりますか？&quot;">​</a></h3><p>表示上の換算値は変わる場合がありますが、<strong>元の取引金額は変わりません</strong>。</p><h3 id="q2-レートが正しくない気がします" tabindex="-1">Q2：レートが正しくない気がします <a class="header-anchor" href="#q2-レートが正しくない気がします" aria-label="Permalink to &quot;Q2：レートが正しくない気がします&quot;">​</a></h3><p>右上の更新ボタンでレートを更新してください。ネットワーク環境によっては更新に失敗する場合があります。</p><hr><p><strong>最終更新</strong>：2026 年 5 月</p>',32)])])}const q=e(i,[["render",o]]);export{p as __pageData,q as default};
